const STATES=new WeakMap(),TAU=Math.PI*2;
const finite=(n,f=0)=>Number.isFinite(n)?n:f;
// Numeric stamping keeps the additional animated cues allocation-free.
function stamp(state,mesh,index,x,y,z,sx=1,sy=1,sz=1,rx=0,ry=state.yaw,rz=0){const o=state.object;o.position.set(x,y,z);o.rotation.set(rx,ry,rz);o.scale.set(sx,sy,sz);o.updateMatrix();mesh.setMatrixAt(index,o.matrix);}
const phaseAt=(time,phase,period)=>((time+phase)%period+period)%period;
const PALETTES=[['#7a886f','#aeb79a','#54774f','#725d48'],['#7d9594','#c0c9b3','#658a77','#726956'],['#777c94','#b5b7c6','#738299','#625a69']];
