  const cores=instances(octa(.31),m.crystal,nodes.length,'crystal-nodes'),shells=instances(box(.42,1.03,.68),m.shell,nodes.length*2,'retracting-crystal-shells'),shards=instances(octa(.085),m.dark,nodes.length*3,'spent-crystal-shards'),cracks=instances(box(.022,.44,.018),m.dark,nodes.length*2,'crystal-fractures');
